function rotatedIndexOf(nums: number[], target: number): number {
  const n = nums.length;
  let lo = 0, hi = n - 1;
  while (lo < hi) { // index of the smallest value
    const mid = (lo + hi) >> 1;
    if (nums[mid] > nums[hi]) lo = mid + 1;
    else hi = mid;
  }
  const start = lo;
  // values <= the last item live in the low run [start, n-1]; bigger ones in [0, start-1]
  if (target <= nums[n - 1]) { lo = start; hi = n - 1; }
  else { lo = 0; hi = start - 1; }
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

